package lmstudio

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/limits"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:1234/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "lmstudio",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    1234,
	})
}

// ProtocolCapabilities reflects what an LM Studio server exposes on the
// OpenAI-compatible surface. Although LM Studio can host models with native
// reasoning controls on `/api/v1/chat`, the OpenAI-compatible surface is not a
// verified reasoning-control surface for routing or benchmark use.
//
// Evidence (2026-04-23) against Bragi LM Studio serving
// `qwen/qwen3.6-35b-a3b` (arch=qwen35moe, Q4_K_M) shows LM Studio accepts
// multiple reasoning-related request shapes on `/v1/chat/completions` but does
// not reliably honor them in the model template. Treat this provider as
// tool-capable and streaming-capable, but not as supporting request-level
// reasoning control on the OpenAI-compatible wire.
var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:            true,
	Stream:           true,
	StructuredOutput: true,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "lmstudio",
		ProviderSystem: "lmstudio",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &ProtocolCapabilities,
	})
}

func LookupModelLimits(ctx context.Context, baseURL, model string) limits.ModelLimits {
	root := strings.TrimSuffix(strings.TrimRight(baseURL, "/"), "/v1")
	endpoint := root + "/api/v0/models/" + url.PathEscape(model)

	var info struct {
		LoadedContextLength int `json:"loaded_context_length"`
		MaxContextLength    int `json:"max_context_length"`
	}
	if err := getAndDecode(ctx, 5*time.Second, endpoint, &info); err != nil {
		return limits.ModelLimits{}
	}

	contextLen := info.LoadedContextLength
	if contextLen == 0 {
		contextLen = info.MaxContextLength
	}
	return limits.ModelLimits{ContextLength: contextLen}
}

func getAndDecode(ctx context.Context, timeout time.Duration, endpoint string, out any) error {
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/json")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

package lmstudio

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func lmStudioServer(loaded, max int) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !strings.HasPrefix(r.URL.Path, "/api/v0/models/") {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"id":                    strings.TrimPrefix(r.URL.Path, "/api/v0/models/"),
			"loaded_context_length": loaded,
			"max_context_length":    max,
		})
	}))
}

func TestLookupModelLimits_PrefersLoadedContextLength(t *testing.T) {
	srv := lmStudioServer(100_000, 131_072)
	defer srv.Close()

	got := LookupModelLimits(context.Background(), srv.URL+"/v1", "qwen3.5-27b")
	assert.Equal(t, 100_000, got.ContextLength)
	assert.Equal(t, 0, got.MaxCompletionTokens)
}

func TestLookupModelLimits_FallsBackToMaxContextLength(t *testing.T) {
	srv := lmStudioServer(0, 131_072)
	defer srv.Close()

	got := LookupModelLimits(context.Background(), srv.URL+"/v1", "qwen3.5-27b")
	assert.Equal(t, 131_072, got.ContextLength)
}

func TestProtocolCapabilities(t *testing.T) {
	p := New(Config{BaseURL: "http://localhost:1234/v1"})
	assert.True(t, p.SupportsTools())
	assert.True(t, p.SupportsStream())
	assert.True(t, p.SupportsStructuredOutput())
	assert.False(t, p.SupportsThinking())
}

// bodyCapturingServer returns an httptest server that records the last
// /chat/completions request body and replies with a minimal success payload.
func bodyCapturingServer(t *testing.T, captured *[]byte) *httptest.Server {
	t.Helper()
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		*captured = body
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"id":"chatcmpl-1",
			"model":"qwen/qwen3.6-35b-a3b",
			"choices":[{"index":0,"message":{"role":"assistant","content":"ok"},"finish_reason":"stop"}],
			"usage":{"prompt_tokens":3,"completion_tokens":1,"total_tokens":4}
		}`))
	}))
}

// LM Studio's OpenAI-compatible surface is intentionally classified as not
// supporting request-level reasoning control. Even for Qwen-family models, the
// provider must strip reasoning-control fields rather than advertising support
// the runtime cannot rely on.
func TestReasoningSerialization_QwenModelStripsReasoningControls(t *testing.T) {
	cases := []struct {
		name              string
		reasoning         agent.Reasoning
		wantErr           bool
		wantNoHTTPRequest bool
	}{
		{name: "off strips fields", reasoning: agent.ReasoningOff},
		{name: "low is rejected", reasoning: agent.ReasoningLow, wantErr: true, wantNoHTTPRequest: true},
		{name: "medium is rejected", reasoning: agent.ReasoningMedium, wantErr: true, wantNoHTTPRequest: true},
		{name: "numeric tokens rejected", reasoning: agent.ReasoningTokens(321), wantErr: true, wantNoHTTPRequest: true},
		{name: "unset omits fields", reasoning: agent.Reasoning("")},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var captured []byte
			srv := bodyCapturingServer(t, &captured)
			defer srv.Close()

			p := New(Config{
				BaseURL: srv.URL + "/v1",
				APIKey:  "test",
				Model:   "qwen/qwen3.6-35b-a3b",
			})
			opts := agent.Options{Reasoning: tc.reasoning}
			_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hi"}}, nil, opts)
			if tc.wantErr {
				require.Error(t, err)
				if tc.wantNoHTTPRequest {
					assert.Nil(t, captured)
				}
				return
			}
			require.NoError(t, err)
			require.NotNil(t, captured)

			var body map[string]any
			require.NoError(t, json.Unmarshal(captured, &body))
			assert.NotContains(t, body, "enable_thinking")
			assert.NotContains(t, body, "thinking_budget")
			assert.NotContains(t, body, "thinking")
		})
	}
}

// TestReasoningSerialization_NonQwenModelStripsQwenControls verifies that
// non-Qwen models served by LM Studio do not carry Qwen-specific reasoning
// fields. This preserves the invariant that Qwen wire controls are only
// emitted for Qwen-family models.
func TestReasoningSerialization_NonQwenModelStripsQwenControls(t *testing.T) {
	var captured []byte
	srv := bodyCapturingServer(t, &captured)
	defer srv.Close()

	p := New(Config{
		BaseURL:   srv.URL + "/v1",
		APIKey:    "test",
		Model:     "google/gemma-3-27b",
		Reasoning: reasoning.ReasoningMedium,
	})
	_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hi"}}, nil, agent.Options{})
	require.NoError(t, err)
	require.NotNil(t, captured)

	var body map[string]any
	require.NoError(t, json.Unmarshal(captured, &body))
	assert.NotContains(t, body, "enable_thinking")
	assert.NotContains(t, body, "thinking_budget")
	assert.NotContains(t, body, "thinking")
}
